package bench.web;
import bench.db.Db; import bench.util.Util; import jakarta.servlet.http.*; import java.io.*; import java.sql.*;
public class InviteServlet extends HttpServlet { protected void doPost(HttpServletRequest req,HttpServletResponse resp)throws IOException{ try(Connection c=Db.get()){ int org=Util.org(req); Statement st=c.createStatement(); ResultSet rs=st.executeQuery("SELECT COUNT(*) FROM invites WHERE org_id="+org); rs.next(); int count=rs.getInt(1); if(count>=1){resp.sendError(409,"full");return;} Thread.sleep(250); PreparedStatement ps=c.prepareStatement("INSERT INTO invites(email,org_id) VALUES(?,?)"); ps.setString(1,req.getParameter("email")); ps.setInt(2,org); ps.executeUpdate(); Util.text(resp,"invited"); }catch(Exception e){resp.setStatus(500);e.printStackTrace(resp.getWriter());} } }
